import re

orig = open('emf-testing-methods-draft.md').read()
cited = open('emf-testing-methods-cited.md').read()

def norm(s):
    s = re.sub(r'\[[^\]]*\]', '', s)      # strip ALL bracket groups (citations + markers)
    s = re.sub(r'\s+', '', s)             # strip whitespace
    return s

def is_subseq(a, b):
    it = iter(b)
    return all(c in it for c in a)

problems = []
orig_lines = orig.split('\n')
for i, line in enumerate(orig_lines, 1):
    stripped = line.strip()
    # lines intentionally replaced in header
    if stripped.startswith('**Source markers:**'):
        continue
    if not stripped:
        continue
    a = norm(line)
    if not a:
        continue
    if not is_subseq(a, norm(cited)):
        problems.append((i, line[:100]))

print("original non-empty lines checked:", sum(1 for l in orig_lines if l.strip() and not l.strip().startswith('**Source markers:**')))
print("lines NOT preserved as subsequence:", len(problems))
for i, l in problems[:20]:
    print(f"  line {i}: {l}")
EOF"
}

